const backend = hasP2PBackend() && window.keatingP2P
	? new P2PStorageBackend(window.keatingP2P)
	: new IndexedDBStorageBackend({
	dbName: "keating",
	version: 2,
	stores: [
		settingsStore.getConfig(),
