let initPromise: Promise<void> | null = null;

export function getInitPromise() {
	if (!initPromise) {
		initPromise = Promise.all([
			syncCustomProviderKeys(),
			keatingStorage.init(),
		]).then(() => {});
	}
	return initPromise;
